import * as React from "react"
import { graphql, Link } from "gatsby"
import Layout from "../../components/layout"
import Seo from "../../components/seo"
import PropTypes from "prop-types"
import kebabCase from "lodash/kebabCase"

import BlogBlock from "../../components/blog-block"

const BlogPage = ({
  data: {
    posts: { edges },
    tags: { group },
    site: {
      siteMetadata: { title },
    },
  },
}) => (

  <Layout>

    <div className="three-col-grid">
      <div>
        <h1>Blog</h1>

        <p>This page contains commentary for a subset of the projects I work on and many of my little thoughts that I thought were worth sharing.</p>

        <p>Posts are ordered by most recent update.</p>

        <h2>Tags</h2>
        <ul>
          {group.map(tag => (
            <li key={tag.fieldValue}>
              <Link to={`/tags/${kebabCase(tag.fieldValue)}/`}>
                {tag.fieldValue} ({tag.totalCount})
              </Link>
            </li>
          ))}
        </ul>

      </div>
      <div className="two-col-grid">{edges.map(edge => <BlogBlock title={edge.node.frontmatter.title} description={edge.node.frontmatter.summary} path={edge.node.frontmatter.slug} tags={edge.node.frontmatter.tags}/>)}</div>
    </div>
    <Link to="/" className="redirect">☞ Go back to the homepage</Link>
  </Layout>
)

export const Head = () => <Seo title="Blog" />

export default BlogPage

BlogPage.propTypes = {
  data: PropTypes.shape({
    posts: PropTypes.shape({
      edges: PropTypes.array.isRequired,
    }).isRequired,

    tags: PropTypes.shape({
      group: PropTypes.arrayOf(
        PropTypes.shape({
          fieldValue: PropTypes.string.isRequired,
          totalCount: PropTypes.number.isRequired,
        })
      ).isRequired,
    }).isRequired,
  }).isRequired,
}


export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    tags: allMarkdownRemark(limit: 2000) {
      group(field: { frontmatter: { tags: SELECT }}) {
        fieldValue
        totalCount
      }
    }
    posts: allMarkdownRemark(sort: { frontmatter: { dateUpdated: DESC }}) {
      edges {
        node {
          id
          frontmatter {
            dateCreated(formatString: "MMMM DD, YYYY")
            dateUpdated(formatString: "MMMM DD, YYYY")
            tags
            summary
            slug
            title
          }
        }
      }
    }
  }
`